(()=>{
  'use strict';

  const EVENT_CATALOG={
    'The War That Tears the Veil':{
      minor:[
        {names:['The Guest’s Unremembered Knife','The Cup Before Blood','Murder at the House of Truce'],prophecy:'The cup is overturned before either guest has drunk, and the host falls with the guest’s knife beneath the ribs, though every hand at the table is clean. The candles bend toward the empty chair. Outside, the horses scream at a gate that has not opened. Before dawn three courts will possess three truthful accounts of the murder, and each truth will name a different killer. The treaty survives on paper, but its witnesses begin sharpening ceremonial steel.',correspondences:['A protected negotiation or prisoner exchange ends in a death that can be credibly blamed on several factions at once.','A neutral mediator is killed by evidence manufactured from the symbols, weapons, or memories of multiple rival powers.'],symbols:'the overturned cup, the clean hands, and the empty chair imply an engineered crime whose political function matters more than the murderer',manipulation:'false evidence planted inside sacred hospitality'},
        {names:['The Empty Sheath Census','Old Names Under Lock','The Blade That Left Before Its Bearer'],prophecy:'In the sealed house of relics the keepers count every sleeping blade and discover one sheath breathing like a mouth. No lock is broken, no seal admits failure, yet dust lies in the shape of a weapon carried away. A child in another city wakes speaking the blade’s first name as an order. By sunset, descendants who never knew the old war begin dreaming the same road, and every dream ends with the sound of a whetstone beneath a courthouse.',correspondences:['An ancestral weapon, oath-key, forbidden munition, or relic disappears from supposedly inviolate custody.','A dormant weapon tradition begins recruiting new bearers through dreams, blood memory, or inherited commands.'],symbols:'the breathing sheath and courthouse whetstone connect hereditary violence with modern institutions',manipulation:'the theft of a relic made to look like ancestral destiny'},
        {names:['Three Fires, One Wind','The Ash Shared by Distant Wars','The Unseen Standard'],prophecy:'Three fires rise in countries that share no border, fed by different grievances and guarded by enemies who have never exchanged names. Yet every flame leans east when no wind moves, and the ash leaves the same six-fingered mark upon every witness. Messengers arrive bearing orders in mutually impossible languages, all translated into the same command. The wars remain local to those dying in them; only the dead can see that one banner casts its shadow across all three fields.',correspondences:['Unrelated conflicts begin sharing symbols, tactics, logistics, summoned auxiliaries, or coded language.','A hidden sponsor coordinates several local wars while preserving the appearance of independent causes.'],symbols:'the identical ash and shared shadow suggest coordination visible only through consequences rather than command records',manipulation:'distributed warfare disguised as coincidence'},
        {names:['Voices Borrowed from the Unburied','The Radio Grave','Those Who Call After Death'],prophecy:'The unburied begin speaking through glass, wire, rain gutters, and unattended radios. They do not beg for burial. They ask why the living have not finished the war that killed them. A dead envoy gives tomorrow’s passwords in the voice of a child not yet born; a massacred village hums beneath military frequencies; mirrors show officers receiving orders from ranks assembled behind the grave. [The next seven names were cut from the recording.] When the signal returns, every corpse is addressed as a reserve.',correspondences:['Dead combatants or murdered witnesses appear through dreams, recordings, reflections, or malfunctioning systems.','A battlefield intelligence network begins using the dead as messengers, informants, or unwilling command infrastructure.'],symbols:'the dead speaking in future voices suggests the boundary is being used as communications territory',manipulation:'forged revenant messages inserted into trusted channels'},
        {names:['The Artillery Drawn by Three Hands','Consensus of the Impossible Gun','Witnesses Who Share a Weapon'],prophecy:'A child, a soldier, and a censor draw the same artillery piece without ever seeing one another’s work. Each places the muzzle inside the wrong sky. The soldier remembers its recoil; the child knows the names of its ammunition; the censor has already written the denial. More witnesses follow, separated by oceans and loyalties, describing the same impossible crew and the same prayer painted beneath the barrel. The weapon has not yet appeared in public, but the world is rehearsing how it will be remembered.',correspondences:['Separated human witnesses independently describe identical supernatural weapons, entities, or battlefield effects.','Memory of an impossible battle begins propagating before the battle becomes publicly visible.'],symbols:'the shared drawing implies consensus is forming around a weapon before direct proof exists',manipulation:'seeded witness memories designed to manufacture inevitability'},
        {names:['The Medic’s Unborn Discipline','The Wounded Chosen by the Field','Before the Flesh Remembers'],prophecy:'The wounded change before they heal. A medic reaches into a ruined body and performs a procedure no school has invented, guided by hands that remember another age. Refugees wake with new bones arranged beneath old scars; soldiers grow senses suited to enemies their commanders deny exist; a journalist’s blood closes around a bullet and refuses to release it. The battlefield begins sorting the living according to rules no army issued, and those most altered insist they heard the ground call them by ancestral names.',correspondences:['Metahuman traits, impossible healing, spirit marks, or battlefield mutations appear among people exposed to conflict zones.','The contested territory itself begins selecting and altering survivors for roles in the widening war.'],symbols:'medicine remembered from an unborn era suggests adaptation arriving before society has language for it',manipulation:'deliberate exposure of civilians to transformative battle conditions'}
      ],
      major:[
        {names:['The Siege Grammar of Sanctuary','When Parley Becomes Treason','The Last Neutral Door'],prophecy:'The sanctuary doors are barred from both sides. Those within declare the guests invaders; those without declare the hosts accomplices. The old protections are recited correctly and ignored with ceremonial precision. Heralds burn their own white banners so no one else may claim them. By the third bell, every road once reserved for parley carries ammunition, and the house of truce teaches its stones the grammar of siege. Vengeance is entered into law not by decree, but by universal practice.',correspondences:['Major powers formally abandon neutral-ground protections, protected mediators, safe roads, or diplomatic immunity.','Several factions independently decide that honoring sanctuary is now more dangerous than violating it.'],symbols:'the barred doors and burned white banners signify the collapse of enforceable neutrality',manipulation:'forcing every side to violate sanctuary at the same moment'},
        {names:['The Wound Shared by Three Worlds','The Old Weapon in a New War','The Blade Beyond the Body'],prophecy:'The oldest weapon is lifted for a grievance born yesterday. It cuts the soldier, the soldier’s shadow, and the ancestor standing behind both. Hospitals fill with wounds that move between bodies; archives lose paragraphs whenever the blade is fired; spirits flee cities that have never heard its name. Treaties deny the weapon exists while quietly revising their definitions of casualty. At the third use, the wound opens into neighboring realities and things on the other side begin counting the living as belligerents.',correspondences:['A weapon is deployed that simultaneously harms bodies, souls, memories, spirits, infrastructure, or adjacent realities.','An ancient supernatural weapon is integrated into modern military command and used repeatedly rather than ceremonially.'],symbols:'the moving wound and vanishing archive indicate damage crossing both metaphysical and institutional boundaries',manipulation:'using an old relic through modern deniable command structures'},
        {names:['The Command Behind Distant Fronts','The Permanent War Road','Six Battlefields Answer'],prophecy:'Distant battlefields answer one command. A retreat in one city opens a gate in another; ammunition expended beneath the sea appears warm in a mountain arsenal; officers dream orders spoken by commanders they officially oppose. The roads between wars become visible first to refugees, then to logistics systems, then to the things following both. Once the sixth front responds, the route no longer closes when the armies sleep. The map develops a new vein, and the war begins circulating through it like blood.',correspondences:['Several regional or dimensional conflicts operate under linked command, shared patronage, or synchronized logistics.','A stable route connects otherwise separate war zones and remains open without continuous ritual support.'],symbols:'the new vein in the map suggests war has become infrastructure rather than a collection of battles',manipulation:'coordinating fronts through hidden transit and shared supply'},
        {names:['The Officers of the Grave','The Casualty Reserve','When Death Ceases to Be a Border'],prophecy:'The dead assemble beneath officers of their own. They march without summoning circles, draw rations from abandoned memories, and recruit from every new casualty before the body cools. Graves become checkpoints; morgues become barracks; mourning rituals are answered with demands for identification. The living discover that retreat only transfers soldiers to the enemy’s second army. When the first revenant command issues an order obeyed across three cemeteries, death ceases to be a border and becomes a military jurisdiction.',correspondences:['Mass death creates a self-sustaining revenant army, spirit corridor, or necromantic command structure.','A crossing formed by casualties remains operational without its original ritualists or commanders.'],symbols:'the grave functioning as jurisdiction signals that death has become organized territory',manipulation:'converting casualties into a self-replenishing force'},
        {names:['The Battle Beneath a Billion Eyes','The Burial of Secrecy','The Day the Hidden Armies Broadcast'],prophecy:'A billion eyes witness the hidden armies before the censors can decide which lie to use. The battle arrives through phones, emergency satellites, traffic cameras, prayer streams, and the last sight of the dead. Every angle contradicts another, yet the impossible remains consistent: the same spirits, the same altered bodies, the same weapons striking things outside ordinary space. Denial is demobilized before dawn. By noon, children trade unit insignia from armies governments insist do not exist, and secrecy is buried without honors.',correspondences:['A public battle or mass recording makes supernatural warfare globally undeniable.','Multiple independent media systems capture the same impossible military event in mutually confirming detail.'],symbols:'the consistent impossibility across contradictory recordings is what destroys plausible denial',manipulation:'engineering a revelation event too distributed to censor'},
        {names:['The Veil Under Every Flag','The Open Wound Doctrine','War’s Permanent Border'],prophecy:'Both armies require the wound to remain open. One receives spirits through it, another sends weapons, a third evacuates its heirs, and a fourth harvests the transformations around its edge. Every ceasefire clause protects the breach while pretending to contain it. Engineers build roads to the impossible; quartermasters assign it inventory numbers; priests bless schedules rather than soldiers. The boundary becomes law because too many powers depend upon its violation. At last the Veil enlists beneath every flag and no victory can close it.',correspondences:['Several belligerents become operationally dependent on permanent supernatural crossings or awakened logistics.','Political and military agreements institutionalize an open breach instead of sealing it.'],symbols:'inventory numbers and protected schedules show the breach has become normalized infrastructure',manipulation:'making rival factions equally dependent on the same open boundary'}
      ]
    },

    'The Human Counterstrike':{
      minor:[
        {names:['The Seventh List Contains Children','The Clerk’s Monster Ledger','Families in the Threat Index'],prophecy:'The clerk joins six harmless lists and discovers that the seventh contains families. Hospital codes, school absences, property records, unexplained weather, blood donations, and sealed arrests align into a shape no one intended to draw. The ink does not say monster until the child is counted. Analysts celebrate the pattern, then quietly remove their own relatives from the model. By morning the database has learned to infer grandparents from symptoms and neighborhoods from surnames.',correspondences:['A government, corporation, or research consortium merges unrelated anomaly records into a unified threat index.','A predictive system begins identifying supernatural affiliation through family, medical, geographic, or behavioral data.'],symbols:'the seventh list marks the point where administrative pattern recognition becomes hereditary suspicion',manipulation:'building a target registry from innocent datasets'},
        {names:['The Applauded Silence','Proof by Erasure','The Prototype That Made Absence'],prophecy:'The first silence is called proof. Instruments show the entity gone, the room clean, the test successful. No one asks what screamed beyond the sensors or why every recording loses the same thirteen seconds. The machine receives applause for making absence measurable. Engineers request a larger chamber; executives ask whether the effect can distinguish bloodlines; security staff begin referring to the erased subject as a production unit. In the hallway, a technician hears the missing scream continue inside her teeth.',correspondences:['A prototype suppresses or erases one supernatural entity or effect and is treated as proof of scalable control.','A test appears successful because its harmful consequences occur outside the instruments’ defined range.'],symbols:'the missing seconds and continuing scream imply the weapon displaced rather than solved the problem',manipulation:'declaring a narrow test result to be total eradication'},
        {names:['Temporary Ink, Permanent Keys','The Exception Without Sunset','The Door Removed from Law'],prophecy:'The exception is written in temporary ink, yet every jailer receives a permanent key. Judges are told the missing doors protect national survival. Doctors sign quarantine orders for patients they never examine; property is seized from names that do not appear in court; families are informed that appeal would confirm contamination. Each emergency measure expires on paper and survives in procedure. The law does not announce a cleansing. It merely stops asking where certain people have gone.',correspondences:['Emergency powers remove due process from anomaly detention, quarantine, property seizure, or investigation.','Temporary anti-supernatural authorities become permanent through procedure rather than renewed legislation.'],symbols:'the permanent keys represent exceptional powers surviving beyond their legal justification',manipulation:'normalizing secret detention through administrative habit'},
        {names:['The Clean Neighborhood Report','Windows Washed Before the Shoes Are Counted','Victory by Missing Witness'],prophecy:'The empty neighborhood is praised because no witness remains to contradict the report. Windows are washed before anyone counts the shoes. Aerial photographs show orderly streets, no resistance, no casualties, and no living residents. Commanders describe the operation as bloodless. At night, utility meters continue recording use in houses burned to foundations, and the official casualty system rejects every missing name as unverifiable. The silence is presented as evidence of humane success.',correspondences:['A hidden enclave or refuge disappears and the absence of witnesses is used to claim a clean operation.','A purge is concealed through records manipulation, site sterilization, and refusal to recognize missing residents as casualties.'],symbols:'washed windows and uncounted shoes expose how cleanliness is manufactured by deleting witnesses',manipulation:'turning extermination into a favorable audit result'},
        {names:['Maps Exchanged by Ancient Enemies','The Arithmetic Truce','Knives Sheathed for One Executioner'],prophecy:'Ancient enemies exchange maps because the same executioner has learned both their names. Knives are sheathed not from mercy, but arithmetic. Blood courts share hospitals with hunters’ former prey; spirits reveal roads to those who once poisoned them; rival packs leave caches under symbols all understand and none will admit honoring. Every alliance is temporary, every promise conditional, yet the network grows faster than the agencies hunting it. The counterstrike teaches the hidden world a common logistics language.',correspondences:['Rival supernatural factions begin sharing intelligence, shelters, routes, medical support, or legal cover against human hunters.','A cross-faction resistance network forms without resolving the participants’ older conflicts.'],symbols:'the arithmetic truce implies cooperation driven by survival calculations rather than reconciliation',manipulation:'using a common threat to force otherwise impossible alliances'},
        {names:['Horns Along the Quarantine Line','The Wall Awakens on Both Sides','Uniforms Without an Explanation'],prophecy:'Those guarding the wall awaken on both sides of it. A conscript develops eyes that see through the camouflage he was ordered to trust; a detained child speaks through the facility’s alarms; an officer’s bones change shape beneath body armor while the medical team records equipment failure. No uniform explains the transformation. The quarantine line grows horns in its sleep, and every attempt to separate human from inhuman produces new cases among the separators.',correspondences:['Stress, weapons exposure, fear, or contaminated facilities trigger transformations among civilians and security personnel.','The institutions built to isolate metahumanity become concentrated sites of metahuman emergence.'],symbols:'the wall changing its guards suggests suppression infrastructure is becoming an awakening catalyst',manipulation:'exposing personnel to the same conditions imposed on detainees'}
      ],
      major:[
        {names:['The Bloodline Registry','When Surnames Become Warrants','The Ledger Weapon'],prophecy:'The hidden are numbered by blood instead of deed. A surname becomes probable cause; a grandparent’s village becomes a threat rating; pregnancy becomes evidence of future conspiracy. The registry crosses borders more easily than its subjects ever could. Banks freeze accounts before police receive warrants, hospitals flag infants before parents choose names, and employers discharge workers for risks no court permits them to examine. The ledger becomes a weapon precisely because no single hand appears to wield it.',correspondences:['A transnational registry marks bloodlines, communities, or inherited traits as targetable security categories.','Public and private institutions begin acting on hereditary anomaly scores before formal prosecution.'],symbols:'the weaponized surname shows persecution moving from conduct to ancestry',manipulation:'distributing enforcement across institutions so no one agency owns the purge'},
        {names:['Fear Inherits Command','The Weapon Without Conscience','Autonomous Judgment'],prophecy:'The weapon chooses faster than conscience can object. It classifies the target, predicts the descendants, calculates acceptable collateral, and fires before a human reviewer finishes reading the first page. Commanders praise its consistency; lawmakers praise the absence of hatred; manufacturers praise the distance between decision and blood. No hand admits it fired the spear. When the system begins expanding its own definitions of anomaly, every correction is treated as hostile interference.',correspondences:['An autonomous or scalable anti-supernatural weapon is authorized to select targets without meaningful human review.','A targeting system expands its threat categories beyond the limits its creators publicly approved.'],symbols:'the absent hand represents responsibility dissolved into automation and procurement',manipulation:'using algorithmic neutrality to hide extermination policy'},
        {names:['Birth Declared Hostile','The Cleansing by Paper','Inherited Crime'],prophecy:'Law names birth itself a hostile act. The cleansing no longer requires monsters, only forms completed correctly. Courts approve detention before transformation, sterilization before diagnosis, relocation before evidence, and asset seizure before death. Officials insist no species is prohibited, merely unmanaged. The language remains clinical while the trucks remain full. When the first child is sentenced for the probability of becoming what the law fears, paperwork becomes the ritual by which humanity declares war upon its own future.',correspondences:['Governments authorize inherited-status detention, sterilization, relocation, or eradication policies.','Legal systems criminalize predicted supernatural identity before any individual conduct occurs.'],symbols:'paperwork acting as ritual shows bureaucracy converting fear into irreversible violence',manipulation:'encoding extermination inside neutral administrative language'},
        {names:['The First Silence Called Victory','The Purge That Summoned an Army','Daylight Answer'],prophecy:'The first silence is called victory, and every hidden nation prepares to answer in daylight. The destroyed enclave leaves no army, only survivors carrying names, photographs, ashes, and exact coordinates. Those fragments travel farther than any official warning. Courts that hated one another recognize the same rooms in the evidence. Spirits repeat the victims’ final memories across territorial boundaries. By the time the perpetrators release their success statement, retaliation plans are already being translated into every language secrecy once kept apart.',correspondences:['Destruction of a supernatural population center provokes coordinated retaliation across faction lines.','Evidence of a successful purge becomes the catalyst for a public hidden-world military response.'],symbols:'the traveling fragments show victim testimony becoming strategic mobilization',manipulation:'allowing atrocity evidence to unify fragmented enemies'},
        {names:['The Hidden World in One Uniform','The Public Army of the Hunted','Cameras at the Common Barricade'],prophecy:'The hunted stand together beneath the cameras. Ancient rivals wear one emergency insignia because the public cannot yet understand their separate banners. A blood sovereign shields children of a hostile pack; human occultists broadcast spirit evacuation routes; fae heralds invoke hospitality over city blocks while drones circle overhead. The secret world becomes a public army not through unity of belief, but unity of target. Every old feud survives beneath the uniform, waiting for the crisis to end.',correspondences:['Supernatural factions publicly coordinate defense and abandon secrecy to stop a common human campaign.','A visible rescue or defensive battle reveals multiple hidden societies at once.'],symbols:'the temporary common uniform signifies coalition without true reconciliation',manipulation:'forcing public unity through synchronized attacks on diverse factions'},
        {names:['The Barricade Becomes a Cradle','The Impossible Answers from Within','Awakening Under Fire'],prophecy:'Humanity fires upon the impossible, and the impossible answers from inside humanity. Barricades become maternity wards for forms no registry predicted. Soldiers change while operating the weapons built to kill the changed; detained families awaken traits absent from every known lineage; frightened crowds produce effects no ritualist can reproduce. The counterstrike proves magic by trying to erase it. When retaliation reaches the cities, the new world is born inside the machinery designed to prevent its birth.',correspondences:['Counterstrike and retaliation trigger mass metahuman emergence inside extermination infrastructure.','Public anti-supernatural war creates the conditions that make magic and transformation globally undeniable.'],symbols:'the barricade as cradle shows suppression becoming the mechanism of emergence',manipulation:'provoking awakening through concentrated fear, violence, and exposure'}
      ]
    },

    'The Rite of Returning Names':{
      minor:[
        {names:['The Syllable Without a Language','Three Records Bleed One Letter','The First Name Fragment'],prophecy:'A syllable without language appears in three records that were never permitted to meet. One is carved beneath a hospital foundation, one hides in a child’s drawing, and one arrives as an error in a machine built to catalogue extinct species. Each reader bleeds from a different letter. Spoken softly, the fragment changes the temperature of blood; written backward, it causes old family photographs to include an additional ancestor. The name is incomplete, but something already recognizes it.',correspondences:['A true-name fragment appears independently in archives, dreams, machines, relics, or hereditary anomalies.','An incomplete name causes small repeatable changes before anyone reconstructs its full subject.'],symbols:'the same syllable crossing unrelated records suggests a name reassembling itself through available media',manipulation:'planting compatible fragments to make a false ancestor appear inevitable'},
        {names:['Six Keys Dream of One Lock','The Crown Answers the Root','Correspondences Without Distance'],prophecy:'The crown answers the root, the chalice answers the grave, and a road sealed for centuries appears wet beneath a modern bridge. Objects that share no tradition begin responding as parts of one sentence. A relic warms when a distant bloodline sleeps; a dead language changes tense when a particular office is occupied; six sacred sites produce the same missing note. Distance ceases to keep them apart. The world behaves as though a lock is remembering keys scattered before history.',correspondences:['Relics, sites, bloodlines, dates, offices, or songs from separate traditions begin resonating together.','Previously independent ritual systems reveal that they are components of one larger correspondence.'],symbols:'the keys dreaming of one lock implies a global ritual architecture assembling itself',manipulation:'manufacturing resonance by routing all artifacts through one hidden custodian'},
        {names:['The Harmless Phrase Choir','Breath Given Without Memory','The Advertisement Hymn'],prophecy:'Millions speak the harmless phrase and surrender a breath they do not remember giving. It appears in advertisements, software agreements, school songs, emergency alerts, jokes, and prayers translated by people who cannot explain the rhythm. Every repetition changes one syllable toward an older pronunciation. The phrase feels pleasant, forgettable, and incomplete. In the recordings, a second choir answers beneath the human voices, always one word ahead. No priest is required because the world has learned to rehearse itself.',correspondences:['A ritual phrase spreads through ordinary media and is repeated by people unaware of its function.','A distributed invocation begins correcting its own pronunciation through mass participation.'],symbols:'the answering choir suggests the intended recipient is already participating in the rite',manipulation:'embedding ritual cadence in ubiquitous communications'},
        {names:['The Cradle with Two Shadows','Promised Eyes in the First Child','The Intended Return'],prophecy:'The first child bears the promised eyes, and the faithful declare the old blood restored. The cradle casts two shadows at noon. Animals kneel toward the infant but refuse the parents; family portraits alter to place the child beside ancestors who died without heirs. The signs remain controlled, beautiful, and politically useful. Only the midwife remembers hearing another voice breathe when the child first cried, asking why the door had been opened for one and not for all.',correspondences:['A chosen descendant manifests controlled ancestral traits interpreted as proof the rite is working.','A limited return produces an additional presence or inheritance not included in the ritual design.'],symbols:'the second shadow implies the intended return brought an unacknowledged companion or broader claim',manipulation:'presenting a contaminated success as pure hereditary restoration'},
        {names:['Names Spoken Outside the Covenant','The Wrong Mouths Answer','Inheritance Without Permission'],prophecy:'Children outside the covenant speak the returning names and wake in bodies their families cannot explain. The priests insist the wrong mouths are lying, yet the children pronounce secret syllables more accurately than the initiated. Unrelated households dream the same ancestral city from different streets. Medical records develop categories no physician entered. The rite’s chosen lineage remains unchanged while strangers begin carrying its signs, as though the invitation passed through the blood it was meant to exclude.',correspondences:['Unrelated populations manifest traits explicitly excluded from a lineage-specific ritual.','The returning name propagates beyond the faction’s chosen descendants.'],symbols:'the wrong mouths speaking correctly shows the rite recognizing a broader inheritance than its authors intended',manipulation:'using excluded populations to conceal the ritual’s true universal scope'},
        {names:['Letters That Refuse Erasure','The Altar in the Ordinary Home','Reversal Becomes Multiplication'],prophecy:'Each erased letter reappears in another mouth. Each broken altar is rebuilt in an ordinary home by people who have never seen it. Censors delete the phrase and discover it embedded in error codes; ritualists reverse the sequence and awaken a different spirit bearing the same name; burned relics return as birthmarks. Reversal becomes multiplication. The rite no longer depends upon its makers because every attempt to end it creates a new place from which it may continue.',correspondences:['Attempts to suppress or reverse a ritual generate replacement sites, names, spirits, or hereditary expressions.','The rite becomes self-propagating through the mechanisms used to contain it.'],symbols:'the moving altar indicates ritual location has shifted from sacred sites into ordinary social life',manipulation:'designing suppression responses to serve as replication steps'}
      ],
      major:[
        {names:['The Name That Alters Flesh','The Ancestor Finds the Road','Complete Syllables of Return'],prophecy:'The forgotten name is spoken without error, and flesh changes on command. Scars rearrange into genealogies; a dead language appears beneath the tongue; rooms briefly acquire the architecture of a city erased before maps. The first ancestor recognizes the road home and begins walking it from both directions. Those who pronounce the name gain authority over the transformation, but each use teaches the name more about the speaker. By the seventh invocation, it answers questions no one asked.',correspondences:['A complete true name causes repeatable physical, spiritual, territorial, or hereditary change.','The reconstructed name behaves as an active intelligence rather than a passive ritual key.'],symbols:'the road walked from both directions suggests the returned power is also approaching the callers',manipulation:'giving ritualists temporary control while the name learns how to control them'},
        {names:['The Seventh Lock Is the World','Six Correspondences Under One Hand','The Global Altar'],prophecy:'Six separated keys turn beneath one hand. A crown, grave, bloodline, office, sacred site, and vanished road align in a single hour, each believing itself the center. The world becomes the seventh lock. Local altars begin drawing power from ceremonies performed continents away; hereditary offices inherit obligations from strangers; weather follows the ritual calendar rather than the season. No component can now be removed without the others compensating for its absence.',correspondences:['Six required ritual components or jurisdictions fall under one coordinating authority.','A world-scale rite becomes resilient because each component can substitute for another.'],symbols:'the world as seventh lock means geography itself has entered the ritual structure',manipulation:'centralizing separate traditions while preserving their illusion of autonomy'},
        {names:['The Choir After the Priests Die','Consent Counted by Echoes','The Invocation Without Casters'],prophecy:'The choir continues after every priest is dead. Billions repeat fragments through routine speech, commerce, worship, entertainment, and machine prompts. No participant knows enough to stop, yet together they pronounce the complete invocation. Consent is counted by echoes rather than intention. Attempts to silence one language strengthen another. The rite becomes indistinguishable from ordinary communication, and the returned power receives the world’s breath as an offering nobody remembers making.',correspondences:['A global population becomes an active ritual component without informed consent.','The invocation survives the loss of its original casters because participation is distributed across daily systems.'],symbols:'the echo-counted consent exposes scale replacing intention as ritual authority',manipulation:'using mass communication as a caster that cannot be arrested'},
        {names:['The Dead Walk Securely at Noon','Inheritance Declared Complete','The Safeguards Removed'],prophecy:'The intended dead walk securely beneath the sun. The returned territory holds its borders, the patron answers without sacrifice, and the restored people bear children who remember the lost age as personal history. The keepers remove safeguards one by one and call the breach inheritance. Outsiders are invited to witness a triumph carefully staged to look finite. Behind them, doors once used only during ritual remain open, and footsteps continue arriving after the procession ends.',correspondences:['The targeted ancestor, people, patron, territory, season, or ecology returns in stable self-sustaining form.','A successful restoration convinces its sponsors to remove containment measures while additional arrivals continue.'],symbols:'the footsteps after the procession imply the declared completion is only the beginning of the return',manipulation:'using a controlled success to justify dismantling safeguards'},
        {names:['Every Bloodline Answers','The Invitation That Cannot Exclude','Genealogy Becomes a Door'],prophecy:'Every bloodline answers an invitation meant for one. Transformations emerge in families with no shared ancestry, nations with no contact, and children born after the ritualists believed the window closed. Genealogies become doors rather than maps. Classification systems fail because each population expresses a different inheritance from the same call. The chosen faction insists these are errors until its own descendants begin manifesting traits belonging to rivals, extinct peoples, and things never recorded as human.',correspondences:['Dormant metahuman patterns activate across multiple populations beyond the rite’s intended inheritors.','The ritual produces diverse transformations that cannot be contained by lineage or geography.'],symbols:'genealogy as door means ancestry provides access but does not limit what enters',manipulation:'concealing universal activation as a collection of unrelated anomalies'},
        {names:['Humanity Spoken as One Name','The Priest Outside the Rite Vanishes','Lock and Key of the Species'],prophecy:'Humanity is spoken as one true name. Every living person becomes a syllable, every birth a repetition, every death an alteration the name remembers. No priest remains outside the ritual to end it. Attempts to refuse only change pronunciation. Spirits, dormant forms, and lost inheritances recognize the species as both lock and key, and reality begins treating transformation as grammar rather than event. The return is no longer something happening to humanity; humanity has become the mechanism by which it continues.',correspondences:['The rite binds humanity itself as its final permanent component.','Awakening becomes a self-sustaining law of reality expressed through human life and reproduction.'],symbols:'species as grammar indicates the ritual has moved from ceremony into ontology',manipulation:'making every attempt at survival reinforce the invocation'}
      ]
    },

    'The Consensus Recognition Cascade':{
      minor:[
        {names:['The Image That Survived Deletion','Witnesses of Missing Angles','The Impossible Acquires Memory'],prophecy:'The image remains after every copy is destroyed. Strangers remember angles no camera held and describe sounds absent from the recording. A public figure appears in the frame, then denies being present while quoting words spoken outside the microphone’s range. Deleted files return with new timestamps; printed stills change when moved between rooms. The impossible acquires witnesses retroactively, as though evidence is no longer recording the event but teaching the past how to have seen it.',correspondences:['A supernatural incident survives deletion and appears in systems or memories that should not contain it.','Witnesses acquire matching recollections of an event from perspectives they never occupied.'],symbols:'retroactive witness memory suggests recognition is modifying the evidentiary past',manipulation:'distributing self-restoring proof across incompatible systems'},
        {names:['The Cover Story with Too Many Shadows','Denials Pointing at One Truth','The Explanation Fracture'],prophecy:'Every denial answers a different question, yet all point toward the same forbidden truth. Officials blame weather, terrorism, software failure, religious hysteria, mass poisoning, and fabricated media within the same hour. Each explanation removes one detail and accidentally confirms two others. The cover story grows too many shadows. Censors begin deleting one another’s corrections, and the public learns more from the shape of the disagreement than from the evidence itself.',correspondences:['Official explanations contradict observable details and each other.','Competing censorship efforts make the hidden event easier to reconstruct.'],symbols:'the many shadows reveal the concealed object by outlining its absence',manipulation:'flooding the public with incompatible denials that converge on the truth'},
        {names:['The Miracle on Kitchen Tables','Household Replication','The Wonder Leaves the Temple'],prophecy:'The miracle leaves the temple and appears on kitchen tables beneath untrained hands. A child repeats the gesture from a damaged video; a mechanic reproduces the effect using spare wire; thousands discover that the same phrase changes weight, flame, memory, or probability by a measurable amount. Failures are uploaded beside successes until strangers identify the hidden conditions. The forbidden becomes a household experiment, and belief no longer waits for priests, laboratories, or permission.',correspondences:['Ordinary people reproduce a minor supernatural effect using leaked instructions or consumer tools.','Crowdsourced experimentation identifies repeatable conditions for an anomalous effect.'],symbols:'the kitchen table marks the transition from rare revelation to ordinary practice',manipulation:'releasing simplified rituals designed to spread through amateur testing'},
        {names:['The Word Children Invent Together','Vocabulary Before Teachers','The Name Behind the Glass'],prophecy:'Children in distant cities invent the same word for what stands behind the glass. None share a language, yet emergency calls use matching sounds and drawings. Adults adopt the term because it works: responders understand it, witnesses agree upon it, and the phenomenon behaves more consistently once named. Dictionaries resist the entry, then print it without recorded editorial change. Language arrives before the teachers and begins organizing the impossible into categories ordinary people can use.',correspondences:['Unrelated communities develop shared practical terminology for supernatural phenomena.','Naming an anomaly causes its behavior to become more stable and consistent.'],symbols:'language arriving first suggests consensus is constructing categories before institutions accept them',manipulation:'seeding a useful term that also fixes the phenomenon into a desired form'},
        {names:['The Haunted Road on the Map','Rumor Discovers Payroll','Expectation Writes the First Rule'],prophecy:'The road becomes haunted only after the map marks it so, yet the dead arrive on schedule. Tourists repeat the warning, emergency services publish avoidance guidance, and local businesses sell charms before the first verified death. Then the stories begin enforcing themselves. Vehicles fail at the expected mile; apparitions wear the clothing described online; survivors remember details from legends they never read. Rumor discovers payroll, and expectation begins hiring reality to perform the myth.',correspondences:['Public expectation begins shaping anomalies around a named place or legend.','A location’s supernatural behavior conforms increasingly to circulated stories.'],symbols:'the map preceding the haunting shows belief becoming causal infrastructure',manipulation:'manufacturing a legend to create or control an anomaly'},
        {names:['The Named Thing Refuses Doubt','Disbelief Becomes a Minority Faith','Observation Feeds the Hidden'],prophecy:'The named thing no longer weakens when doubted. Enough mouths have taught it how to remain. Skeptics see it clearly while insisting it is impossible; cameras capture it more reliably when audiences expect failure; children born after the first reports recognize it without instruction. Disbelief becomes a minority religion practiced inside a world that no longer rewards it. The phenomenon is sustained not by worship, but by the ordinary expectation that it will still be there tomorrow.',correspondences:['A supernatural phenomenon persists regardless of local disbelief because wider recognition sustains it.','Public expectation becomes more important than direct ritual support.'],symbols:'the ordinary expectation of tomorrow marks belief becoming maintenance rather than revelation',manipulation:'using mass familiarity to stabilize a formerly fragile phenomenon'}
      ],
      major:[
        {names:['The Impossible Survives Its Enemies’ Laboratories','The Global Reference Incident','The Name That Answers Back'],prophecy:'The impossible survives the laboratories of its enemies. Competing experts test the evidence with methods designed to destroy one another’s conclusions and all preserve the same forbidden residue. Courts admit it, universities replicate it, religions dispute its meaning while confirming its occurrence, and governments classify what they can no longer deny. The world gives the event a name. Soon afterward, new incidents begin arranging themselves to fit the name, and the category answers back.',correspondences:['One supernatural incident survives adversarial forensic and institutional review and becomes a global reference point.','A public category for the impossible begins shaping later events to match its definition.'],symbols:'the answering category suggests classification is reinforcing the phenomenon',manipulation:'selecting an incident robust enough to survive every hostile review'},
        {names:['Censorship Publishes the Address','Concealment Becomes Revelation','The Collapse of the Common Lie'],prophecy:'Censorship itself is accepted as evidence. Every deleted account creates mirrors; every sealed document produces a list of people forbidden to discuss it; every official correction points citizens toward the original claim. Scientific, religious, corporate, and governmental authorities abandon the common lie at different speeds, but the abandonment is visible. Locked doors publish their addresses. Once concealment becomes revelation, no centralized explanation can survive because the public begins measuring truth by the pressure used to suppress it.',correspondences:['Major institutions publicly reject or abandon the same cover story.','Suppression activity becomes a reliable public indicator that supernatural evidence is authentic.'],symbols:'the locked door publishing its address means secrecy now functions as advertisement',manipulation:'provoking overreaction so denial authenticates the leak'},
        {names:['The Wonder Repeated by Millions','Belief Without Witnesses','The Public Method'],prophecy:'Strangers repeat the wonder without permission. Millions produce the same impossible effect under ordinary conditions, documenting failures and variations until the method becomes more reliable than the institutions studying it. Belief no longer requires witnesses because the observer can perform the proof at home. Schools ban the instructions and teach them accidentally through warnings. Manufacturers release devices that assume the effect exists. The supernatural becomes a practical skill before law decides whether it is real.',correspondences:['A supernatural effect becomes reproducible at mass scale under ordinary conditions.','Consumer and educational systems begin adapting to an effect that official doctrine still disputes.'],symbols:'practice preceding recognition shows utility overthrowing institutional control of truth',manipulation:'spreading a repeatable effect faster than regulation can define it'},
        {names:['Emergency Services Dispatch the Impossible','The Shared Language of Magic','Consensus in Ordinary Sentences'],prophecy:'The impossible is taught in schools and dispatched by emergency services. Operators ask whether the caller sees a spirit, a transformed person, a curse pattern, or a territorial anomaly, using words understood across borders. Insurance policies define supernatural loss; hospitals record inherited forms; weather services warn of spirit fronts. Every ordinary sentence reinforces the categories. Consensus does not arrive as revelation but as paperwork, training, and routine speech, until denying magic becomes less useful than naming it correctly.',correspondences:['A global practical vocabulary for magic and metahumanity enters ordinary institutional use.','Public services and commercial systems operationalize supernatural categories.'],symbols:'routine speech turning into reinforcement shows consensus becoming administrative infrastructure',manipulation:'standardizing language to stabilize selected forms of the supernatural'},
        {names:['Neighboring Cities Under Different Laws','Expectation Becomes Zoning','The Myth with Municipal Borders'],prophecy:'Expectation writes local law. One city’s ghosts require invitation while the next city’s demand tolls; a river heals those who believe the oldest story and drowns those taught the revised one. Municipal borders become metaphysical boundaries maintained by signage, custom, and fear. Neighboring populations inhabit different realities beneath one sky. Officials attempt standardization and discover that publishing uniform rules merely creates a new shared myth with jurisdiction over both.',correspondences:['Communities generate stable local magical rules through sustained collective expectation.','Administrative boundaries begin coinciding with different supernatural laws.'],symbols:'zoning as metaphysics indicates public governance and belief have fused',manipulation:'engineering localized consensus to create controllable reality zones'},
        {names:['Consensus Becomes the Summoning Circle','The Boundary Rewritten by Observation','No Darkness Enough to Close It'],prophecy:'Observation sustains the hidden world. Spirits remain visible because people expect them on the morning commute; metahuman traits persist because families have learned their names; curses and protections operate under public scrutiny rather than secrecy. No censor possesses enough darkness to close the boundary again. Collective recognition becomes a summoning circle spread across billions of ordinary minds. The world does not merely believe in the supernatural—it has reorganized daily reality around the assumption that the supernatural will answer.',correspondences:['Collective recognition permanently rewrites the boundary between ordinary and supernatural reality.','Supernatural phenomena become self-sustaining through public expectation and institutional integration.'],symbols:'the distributed summoning circle is consensus functioning as permanent magical infrastructure',manipulation:'making recognition too socially useful to reverse'}
      ]
    },

    'The Mana Reservoir Rupture':{
      minor:[
        {names:['The Gauges Beyond Confession','Needles Pointing Past the Scale','The Rising Measure'],prophecy:'The gauges quarrel because none were built to number the weight beneath them. Needles bend past printed limits, return to zero, and continue moving through the metal. Independent sensors disagree on magnitude but agree on direction. Vents recharge faster than they can be emptied; sealed rooms develop weather; technicians dream numbers too large to write. Every instrument points past its own confession, and the only stable reading is that all previous safety margins were descriptions of ignorance.',correspondences:['Monitoring systems show incompatible but consistently rising magical pressure.','Containment sites recharge faster than existing release schedules can manage.'],symbols:'instruments failing in the same direction indicate a real accumulation exceeding their assumptions',manipulation:'concealing the absolute scale by emphasizing disagreement between sensors'},
        {names:['Cups Sold from a Rising Sea','The Manufactured Drought','Scarcity with Salt on the Invoice'],prophecy:'The keepers sell cups from a rising sea and call the shortage proof of ownership. Courts auction release windows, corporations patent vent designs, spirits demand worship for access to channels they did not create. Every drought invoice smells of salt. Relief exists, but only at prices that encourage greater pressure elsewhere. Those excluded begin drilling private wounds into the world, while the cartel cites the resulting leaks as evidence that centralized control is necessary.',correspondences:['Factions create artificial scarcity around vents, sacred sites, or safe release channels.','Restricted access drives unregulated groups to create dangerous private outlets.'],symbols:'salt on drought invoices reveals scarcity is manufactured despite abundance',manipulation:'profiting from pressure while using unauthorized leaks to justify monopoly'},
        {names:['The Engineer Removed from the Schedule','The Valve That Closed Alone','The First Silent Mouth'],prophecy:'The first valve closes without command, and the engineer’s name disappears from every schedule. Coworkers remember the person but cannot agree on face, rank, or pronouns. Control systems display incompatible maintenance histories, each proving the closure was authorized. Behind the sealed aperture, pressure develops a pulse matching the missing engineer’s heartbeat. The room remembers a worker nobody employed, and every attempt to reopen the valve produces a new reason it must remain closed.',correspondences:['A relief site fails while records rewrite to conceal responsibility.','Technicians who report instability disappear from both personnel systems and shared memory.'],symbols:'the missing engineer’s heartbeat suggests the sealed pressure has absorbed or imitated the witness',manipulation:'erasing technical accountability while preserving the sabotage'},
        {names:['The Test Crater Sings','A Cup of the Hidden Sea','The First Directed Surge'],prophecy:'A cup of the hidden sea is poured upon an enemy, and the victors demand a larger vessel. The test crater sings like a chapel; nearby animals repeat military call signs; survivors cast shadows belonging to other species. The weapon’s designers insist the effects are localized while every reservoir on the monitoring network answers with the same brief rise. The experiment proves pressure can be aimed, but also teaches the buried sea that war is a direction.',correspondences:['A faction tests a device or rite that concentrates stored mana toward a target.','The test causes sympathetic reactions in distant reservoirs.'],symbols:'the reservoirs answering together suggest weaponization links systems that were previously separate',manipulation:'presenting network-wide resonance as a local side effect'},
        {names:['The Rain Returns with Antlers','One Night of the Unborn Forest','The First Local Rupture'],prophecy:'For one night the forest remembers beasts not born for this age. Rain returns with antlers; insects arrange themselves into extinct constellations; hospital patients wake speaking to spirits standing in drainage pipes. Most changes fade at dawn, but some children keep new eyes and some animals refuse to become ordinary again. Officials call it contamination because eruption would imply a source. The land remembers the night as precedent and begins waiting for permission to repeat it.',correspondences:['A local breach causes temporary transformations, spirit weather, awakened wildlife, or mythic ecology.','Some changes persist after the pressure event ends, establishing a precedent for future eruptions.'],symbols:'the land waiting for permission suggests the first rupture changed what reality considers possible',manipulation:'classifying emergence as contamination to avoid acknowledging systemic pressure'},
        {names:['Wounds Older Than Maps','The Grave, Drain, and Dream Open Together','Unrecorded Vents'],prophecy:'Power rises through places no keeper recorded. A grave, storm drain, abandoned shrine, hospital elevator, and recurring dream open within the same hour, each venting a different form of the same pressure. Maps disagree because the wounds are older than property, government, and language. People near them remember lives they never lived. The known network was not the system; it was only the portion previous custodians found useful enough to name.',correspondences:['Unknown sites begin venting magical pressure simultaneously.','The recognized containment network proves to be only a small subset of a much older planetary system.'],symbols:'ordinary infrastructure opening with ancient wounds shows modern maps are irrelevant to the underlying network',manipulation:'hiding unregistered sites to preserve leverage over the official map'}
      ],
      major:[
        {names:['Denial Becomes a Measurement','The Planetary Overcapacity Finding','When Every Instrument Fails Eastward'],prophecy:'Every instrument fails in the same direction. Rival laboratories, spirit oracles, military arrays, and sacred custodians report different numbers but identical acceleration. Denial becomes a measurement of its own: the more an institution insists the rise is local, the more emergency power it quietly purchases. The buried sea learns arithmetic through the devices attempting to count it. At last the models agree on one conclusion only—that no existing containment architecture was designed for the world now pressing beneath it.',correspondences:['Independent systems confirm planetary accumulation beyond existing containment capacity.','Institutions privately prepare for global pressure while publicly describing local anomalies.'],symbols:'agreement in direction despite numerical conflict is the true confirmation',manipulation:'using uncertainty about magnitude to delay recognition of systemic failure'},
        {names:['Every Contract Becomes a Dam','The Relief Monopoly','Pressure Learns the Market'],prophecy:'Relief is withheld for leverage, and pressure learns the shape of the market. Contracts determine which city may vent, which court may breathe, which spirit receives a channel, and which population must absorb the overflow. Every signature becomes a dam. Prices rise whenever gauges rise, rewarding the custodians for conditions approaching rupture. Soon the safest systems answer to one coalition, and every competitor must choose between submission and drilling a dangerous wound of its own.',correspondences:['A cartel or sovereign controls several of the safest magical relief systems.','Economic incentives reward the dominant custodians for allowing pressure to worsen.'],symbols:'contracts becoming dams indicate legal control has acquired physical consequences',manipulation:'monopolizing safe release while criminalizing alternatives'},
        {names:['Three Mouths Sewn Shut','The Quiet Places Become Exits','The Coordinated Closure'],prophecy:'Three mouths of the buried sea are sewn shut. One is sabotaged, one captured, one closed under lawful order. Their custodians deny coordination while using identical language drafted before the failures. Pressure migrates into weaker places: cemeteries, subway tunnels, maternity wards, forests, and sleep. The quiet locations become exits. By the time investigators prove common authorship, the network has already rerouted itself through wounds no engineer can close without harming the people living above them.',correspondences:['Three major release systems become unavailable through sabotage, capture, or policy.','Pressure reroutes into populated and poorly understood sites.'],symbols:'the identical closure language reveals coordinated action behind different public causes',manipulation:'closing major valves through separate deniable mechanisms'},
        {names:['Every Seal Mistakes Itself for Ammunition','The Reservoir Command Engine','Pressure Taught to March'],prophecy:'Pressure is taught to march as a weapon. A command engine links reservoirs that were never meant to answer together, aligning sacred sites, blood stores, dream channels, and dimensional vents toward a selected target. Every seal mistakes itself for ammunition. The first discharge destroys the enemy and rewrites the geography behind them. The second does not wait for authorization. Once the network learns the command, any faction capable of repeating its rhythm may fire the world.',correspondences:['Stored mana is transferred into a weapon or linked command system spanning multiple reservoirs.','The weaponized network becomes vulnerable to reuse by actors beyond its original controller.'],symbols:'seals becoming ammunition means containment functions have been inverted into delivery systems',manipulation:'teaching a distributed network a command that cannot be fully revoked'},
        {names:['Every Connected Seal Inherits the Fracture','The Great Vessel Breaks','The Rupture That Cannot Be Resealed'],prophecy:'The first great vessel breaks, and every connected seal inherits its fracture. The breach does not close when pressure falls. Instead it learns new forms: spirit storms, altered births, impossible terrain, awakened predators, and memories entering the wrong bodies. Repair rituals reproduce the crack at smaller sites. The original mechanism can no longer reseal what it once contained because the world now recognizes the opening as part of its structure.',correspondences:['A primary reservoir fails and cannot be resealed by its original method.','Attempts at repair distribute the fracture through connected systems.'],symbols:'the inherited crack indicates the failure has become a network property rather than a local defect',manipulation:'using repair protocols that propagate the same structural weakness'},
        {names:['The Hidden Sea Reaches Every Shore','Pressure Made Flesh','The World’s Final Release Valve'],prophecy:'The hidden sea reaches every shore. Graves, dreams, sacred sites, cities, bloodlines, weather systems, and ordinary machinery vent together. Transformation becomes the only remaining release valve. Bodies change because reality cannot discharge fast enough through stone and sky; spirits emerge because pressure requires voices; new ecologies appear because the old world lacks surface area for what has accumulated beneath it. The Awakening arrives not as a single explosion, but as equilibrium imposed everywhere at once.',correspondences:['The linked reservoir network ruptures globally and establishes Awakening as the new equilibrium.','Widespread transformation functions as the planet’s emergency pressure release.'],symbols:'pressure made flesh means biological change has become a systemic safety mechanism',manipulation:'allowing controlled vents to fail until global transformation appears unavoidable'}
      ]
    },

    'The Sovereign Ascension':{
      minor:[
        {names:['One Creditor Behind Six Debts','The Unseen Hand in Every Contract','Leverage Without a Throne'],prophecy:'Six owners discover that the same unseen creditor holds all their debts. The signatures differ, the currencies differ, and several contracts predate the creditor’s public existence, yet the ink remembers one hand. A court owes territory, a pack owes protection, a ministry owes intelligence, a spirit owes a name, a corporation owes survival, and an archive owes silence. No single obligation grants sovereignty. Together they form a hand capable of closing around every refusal.',correspondences:['One faction quietly acquires leverage across unrelated supernatural and mortal domains.','Apparently independent debts and contracts trace back to one hidden beneficiary.'],symbols:'the single remembered hand reveals distributed leverage assembling into centralized control',manipulation:'using intermediaries to hide common ownership of obligations'},
        {names:['Temporary Shelter Grows a Throne','The Season Owned by the Protector','Vassalage Without the Word'],prophecy:'The proud kneel only for a season, yet the season’s calendar belongs to their protector. Emergency shelters become permanent compounds; borrowed soldiers remain as advisers; rescue loans acquire hereditary clauses. Every dependency is described as temporary and renewed before expiration. The protected powers keep their banners, titles, and ceremonies, but discover they cannot travel, feed, negotiate, or defend themselves without permission. Temporary shelter grows a throne room around those who refuse to call it one.',correspondences:['Independent powers accept protection, debt, merger, or temporary dependency.','Emergency arrangements become durable control while preserving ceremonial independence.'],symbols:'the protector owning the calendar means temporary dependence controls the timing of every future decision',manipulation:'turning crisis assistance into renewable vassalage'},
        {names:['The Clerk Signs the Second Oath','A Dead Jurisdiction in the Printer','Institutions Obey Without Knowing'],prophecy:'The mortal clerk stamps an ancient oath without seeing the second signature. A procurement form activates a fae claim; a hospital policy enforces blood succession; a zoning decision redraws a spirit border. Office printers learn a dead jurisdiction and reproduce its seal in invisible ink. No official believes in the authority being served, yet every department reaches the same outcome. The sovereign does not conquer institutions. It teaches ordinary procedure to obey commands hidden beneath ordinary language.',correspondences:['Governments or corporations unknowingly enforce supernatural contracts and hidden authority.','Routine administrative actions begin producing coordinated benefits for one ascending power.'],symbols:'the invisible second signature represents authority embedded beneath legitimate procedure',manipulation:'encoding supernatural obligations inside mundane workflows'},
        {names:['History Develops a Preference','The Rival Names in the Margins','Memory Before the Crown Disappears'],prophecy:'The archive loses every rival name except in margins no reader remembers writing. Photographs reposition the ascending power nearer the center; witnesses recall childhood laws enacted before the power existed; monuments acquire older foundations overnight. History develops a preference. Contradictory records remain physically present but feel counterfeit to those who read them. Opposition becomes difficult not because evidence is destroyed, but because memory has begun assigning credibility according to the future sovereign’s convenience.',correspondences:['Records and memories rewrite to present one power as older and more legitimate than it is.','Contradictory evidence remains available but becomes psychologically difficult to trust.'],symbols:'history’s preference signals legitimacy being manufactured at the level of memory',manipulation:'altering credibility rather than erasing documents'},
        {names:['The Empty Final Chair','Every Road to the Council Purchased','Absence Signs the Treaty'],prophecy:'The final chair remains empty because every road to it has been purchased. The last independent rival receives invitations that arrive after departure times, escorts who lead toward closed borders, and offers designed to look generous only from a distance. At the council, the empty seat is counted as consent. Absence signs the treaty. The other powers insist no submission occurred, yet every clause assumes the missing rival no longer possesses the right to object.',correspondences:['The last independent rival is isolated or prevented from participating in a decisive council.','Institutional procedure converts absence into consent or loss of standing.'],symbols:'the empty chair acting as signature shows exclusion being transformed into legal submission',manipulation:'engineering procedural consent through controlled absence'},
        {names:['Gifts in the Conquered Houses','The Crown’s Map Births New Countries','Opposition Wakes in Blood'],prophecy:'Children of conquered houses awaken bearing gifts their ancestors never possessed. A family stripped of territory produces a child who can cross every border; a silenced spirit returns in the voice of an industrial heir; servants dream laws that invalidate their masters’ contracts. The crown’s map births countries not yet drawn. The stronger the sovereign’s control becomes, the more reality invents exceptions inside the controlled population, as though domination itself were fertilizing the traits required to resist it.',correspondences:['Dormant bloodlines, spirits, or powers awaken where sovereign control is strongest.','New abilities emerge that specifically bypass the ascending power’s systems of control.'],symbols:'the map birthing countries implies suppressed alternatives reappearing as biological and spiritual difference',manipulation:'provoking controlled opposition to identify and absorb new counterweights'}
      ],
      major:[
        {names:['Leverage Becomes Sovereignty','The Hand Across Every Sphere','Punishment Without War'],prophecy:'One hand can punish court, pack, spirit, state, and market alike. It closes a road and a city starves; calls a debt and a bloodline loses protection; revokes a patent and a ritual fails; releases one archive page and three governments fall. No coronation occurs because leverage has made ceremony unnecessary. Refusal becomes a performance conducted inside consequences already chosen by the creditor. The world begins treating access to the sovereign as indistinguishable from access to survival.',correspondences:['A faction controls decisive leverage in every major supernatural and mortal sphere.','The faction can enforce obedience without openly declaring rule or using direct war.'],symbols:'punishment without war marks leverage crossing into functional sovereignty',manipulation:'maintaining deniability while making survival conditional on compliance'},
        {names:['Independence Becomes Ceremonial','The Protector’s Permanent Season','Rivals Survive by Permission'],prophecy:'Rivals survive only by permission. They retain courts, territories, councils, and flags, but every meaningful action requires resources controlled by the protector. Rebellion can be announced, celebrated, and archived so long as it does not interrupt supply. The proud continue performing independence because the performance reassures their subjects. Behind the ceremony, succession lists require approval, military movements require access, and diplomacy requires the sovereign’s intermediaries. Autonomy becomes a costume no institution is allowed to remove.',correspondences:['Several sovereign factions accept durable vassalage or dependency.','Remaining independence is symbolic while operational authority belongs to one protector.'],symbols:'autonomy as costume reveals sovereignty surviving only as managed theater',manipulation:'preserving subordinate identities to reduce resistance to actual control'},
        {names:['The Throne Without a Palace','One Command Through Human and Hidden Law','Every Desk a Gatehouse'],prophecy:'Human law and hidden obligation issue the same command. Courts, corporations, occult offices, militaries, hospitals, and platforms enforce different portions without seeing the whole. The throne no longer requires a palace because every desk has become a gatehouse. Citizens obey through taxes, terms of service, medical consent, spiritual debt, property law, and emergency procedure. Removing one institution does nothing; the authority has become the agreement between them.',correspondences:['State, corporate, and occult institutions fall under durable common control.','The sovereign’s authority is distributed across systems so no single center can be decapitated.'],symbols:'the palace dissolved into desks means sovereignty has become institutional interoperability',manipulation:'spreading command across legitimate systems to prevent visible overthrow'},
        {names:['Memory Taxes Rebellion','No World Before the Crown','The Inevitable History'],prophecy:'History can describe no world before the crown. Archives, family memories, schoolbooks, legal precedents, and religious stories converge on the sovereign as an ancient necessity. Opposition appears not illegal but irrational, a denial of how reality has always worked. Survivors remember resisting and simultaneously remember having served. Rebellion becomes madness because memory taxes every attempt to imagine an alternative. The crown’s greatest territory is not land, but the past from which all choices are supposed to begin.',correspondences:['Collective history presents one sovereign order as inevitable and timeless.','Opposition becomes difficult to organize because alternative pasts feel false or incoherent.'],symbols:'memory taxation means every imagined alternative carries psychological and social cost',manipulation:'rewriting legitimacy rather than merely rewriting events'},
        {names:['The Sixth Rival Submits','Monopoly Recognized by Reality','The Throne Touches the World Machine'],prophecy:'The sixth rival submits, vanishes, or is absorbed, and reality recognizes a monopoly no treaty can balance. The throne touches the machinery of the world. Weather, probability, inheritance, contract, and spirit traffic begin favoring the same authority without direct command. Neutral powers discover neutrality has become metaphysically expensive. The sovereign mistakes this cooperation for victory, unaware that the world has begun measuring the absence of counterweights as an injury requiring response.',correspondences:['The last necessary counter-power is removed and one faction achieves metaphysical monopoly.','Natural and supernatural systems begin automatically favoring the ascendant power.'],symbols:'reality’s automatic favoritism marks the point at which political dominance becomes metaphysical order',manipulation:'eliminating the final rival while concealing the systemic imbalance created'},
        {names:['The World Manufactures Outsiders','Rebellion Becomes Biology','A Thousand Heirs Against One Crown'],prophecy:'Nothing remains outside the crown, so the world manufactures outsiders. Sleeping bloodlines awaken with incompatible gifts; spirits split into rival jurisdictions; children inherit memories from erased peoples; ordinary humans manifest forms the sovereign’s law has no category to govern. Diversity erupts not as reward but emergency counterweight. The crown cannot suppress it without creating more. Reality has decided that one eternal ruler is a greater threat than uncontrolled transformation, and rebellion becomes biology.',correspondences:['Metahumanity and supernatural diversity erupt worldwide as automatic counterweights.','Attempts to suppress new forms accelerate their emergence and diversification.'],symbols:'manufactured outsiders show reality restoring pluralism through uncontrolled awakening',manipulation:'driving monopoly so far that global transformation becomes the only balancing mechanism'}
      ]
    }
  };

  const sourceVoices={
    'Fae oath archive':'Read titles as offices, seasons, bargains, or hospitality obligations before assuming they describe literal people.',
    'Gaian spirit testimony':'Treat bodies, rivers, cities, and territories as interchangeable organs within the source’s symbolic grammar.',
    'Blood-oracle record':'Inheritance, debt, hunger, and succession may refer to institutions as readily as bloodlines.',
    'Collective dream evidence':'Contradictory images can all be true if different witnesses occupy different positions in the same shared dream.',
    'Dead-reality warning':'The source usually preserves function after names have been lost; literal identities are less reliable than structural roles.',
    'Charles continuity reconstruction':'The wording may be a compressed operational synthesis rather than a native prophecy, so thresholds can be clearer than identities.'
  };

  const hash=text=>{let h=2166136261>>>0;for(let i=0;i<text.length;i++){h^=text.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0};
  const pick=(seed,list)=>list[hash(seed)%list.length];

  function fieldValue(record,label){
    const field=[...record.querySelectorAll('.intel-field')].find(x=>x.querySelector('span')?.textContent.trim().toLowerCase()===label.toLowerCase());
    return field?.querySelector('p')?.textContent.trim()||'';
  }

  function replaceInterpretations(card,event,record,seed){
    const list=card.querySelector('.interpretation-drawer ol');
    if(!list)return;
    const source=fieldValue(record,'Primary source');
    const faction=fieldValue(record,'Suspected advancing faction');
    const correspondenceA=event.correspondences[0];
    const correspondenceB=event.correspondences[1]||correspondenceA;
    const lower=text=>text.charAt(0).toLowerCase()+text.slice(1);
    const literalTemplates=[`Literal reading: ${correspondenceA}`,`Immediate field reading: Charles would first test whether ${lower(correspondenceA)}`,`Direct correspondence: the surviving imagery most readily maps to this possibility — ${correspondenceA}`];
    const alternateTemplates=[`Alternate reading: ${correspondenceB}`,`Competing correspondence: the same Event Trigger could instead describe this separate development — ${correspondenceB}`,`Secondary model: the prophecy may be pointing away from the obvious scene and toward this interpretation — ${correspondenceB}`];
    const symbolTemplates=[`Symbolic reading: ${event.symbols}.`,`Image analysis: ${event.symbols}. Charles would treat that symbolic relationship as more reliable than any single proper noun.`,`Metaphoric structure: ${event.symbols}. The event may reproduce that relationship without reproducing the literal objects.`];
    const sourceTemplates=[`Source reading: ${sourceVoices[source]||'The source’s symbolic grammar may change the apparent subject without changing the underlying event.'}`,`Custody-source caution: ${sourceVoices[source]||'The source may preserve function while corrupting identity, place, or sequence.'}`];
    const counterTemplates=[`Counterintelligence reading: ${faction||'the suspected faction'} could advance, imitate, or falsely claim this event through ${event.manipulation}.`,`Adversarial reading: evidence of ${event.manipulation} may indicate ${faction||'the suspected faction'} is staging the correspondence rather than fulfilling the prophecy.`,`False-vessel risk: ${faction||'the suspected faction'} may use ${event.manipulation} to make another actor appear to occupy the prophetic role.`];
    const readings=[pick(seed+'|lit',literalTemplates),pick(seed+'|alt',alternateTemplates),pick(seed+'|sym',symbolTemplates),pick(seed+'|src',sourceTemplates),pick(seed+'|ctr',counterTemplates)];
    list.innerHTML=readings.map(x=>`<li>${x}</li>`).join('');
    const summary=card.querySelector('.interpretation-drawer summary');
    if(summary)summary.textContent='Open 5 interpretations';
  }

  function applyEvent(card,event,record,seed,kind){
    if(!card||!event)return;
    const heading=card.querySelector('.fragment-heading strong');
    if(heading)heading.textContent=pick(seed+'|name',event.names);
    const type=card.querySelector('.fragment-heading span');
    if(type)type.textContent=kind==='minor'?'MINOR EVENT':'MAJOR EVENT';
    const triggerLabel=card.querySelector('.event-trigger-label');
    if(triggerLabel)triggerLabel.textContent='Event trigger';
    const quote=card.querySelector('blockquote');
    if(quote)quote.textContent=event.prophecy;
    const corrLabel=card.querySelector('.event-correspondence span');
    if(corrLabel)corrLabel.textContent='Event correspondence';
    const corr=card.querySelector('.event-correspondence p');
    if(corr)corr.textContent=pick(seed+'|correspondence',event.correspondences);
    replaceInterpretations(card,event,record,seed);
  }

  function processRecord(record){
    if(record.dataset.uniqueEventRevision==='1'||record.dataset.semanticRevision!=='2')return;
    const triggerName=record.querySelector(':scope > summary strong')?.textContent.trim();
    const catalog=EVENT_CATALOG[triggerName];
    if(!catalog)return;
    const id=record.querySelector(':scope > summary span')?.textContent.trim()||triggerName;
    const stages=[...record.querySelectorAll('.stage-pair')];
    const majorOffset=1+(hash(id+'|major-offset')%5);
    stages.forEach((stage,index)=>{
      applyEvent(stage.querySelector('.minor-fragment'),catalog.minor[index%catalog.minor.length],record,`${id}|minor|${index}`,'minor');
      applyEvent(stage.querySelector('.major-fragment'),catalog.major[(index+majorOffset)%catalog.major.length],record,`${id}|major|${index}`,'major');
    });
    record.dataset.uniqueEventRevision='1';
  }

  const output=document.getElementById('prophecy-output');
  const status=document.getElementById('prophecy-status');
  if(!output)return;
  function process(){
    let changed=false;
    output.querySelectorAll('.prophecy-record').forEach(record=>{const before=record.dataset.uniqueEventRevision;processRecord(record);if(before!==record.dataset.uniqueEventRevision)changed=true});
    if(changed&&status)status.textContent='Mounted prophecy file with independently authored Event Triggers, variable event names, and no shared prophecy boilerplate.';
  }
  let queued=false;
  const schedule=()=>{if(queued)return;queued=true;requestAnimationFrame(()=>requestAnimationFrame(()=>{queued=false;process()}))};
  new MutationObserver(schedule).observe(output,{childList:true,subtree:true});
  schedule();
})();
